import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`dropshipping`,heroTitle:`Source your next product in minutes`,heroSubtitle:`Perplexity Computer finds suppliers, compares landed costs, and builds your product card — automatically.`,inputUrlCta:`Source this product`,inputUrlPlaceholder:`e.g. https://www.tiktokshop.com/product/...`,inputUrlPrefill:`Go to {url} and identify the exact product being sold. Then search AliExpress for every supplier selling this product or close variants. Compare unit cost, shipping speed, minimum order quantity, and seller rating across all suppliers found. Calculate the estimated landed cost (product + shipping + fees) and projected profit margin at three retail price points: $29.99, $39.99, and $49.99. Check whether the product name, brand, or design has any trademark or intellectual property issues that could cause problems on Shopify or Amazon. Finally, export a one-page product card that includes: 1) Product name and description, 2) Top 3 supplier links ranked by cost and reliability, 3) Full margin breakdown at each price point, 4) Shipping time estimates to the US, 5) IP/trademark risk summary, and 6) Sample order instructions for the best supplier.`,heroOverlaySteps:[`Identifying the exact product, category, and specifications from the URL`,`Searching AliExpress for every supplier selling this product or close variants`,`Comparing unit costs, shipping speeds, and calculating margins at three price points`,`Product card with supplier links, margin breakdown, and sample order instructions — ready to act on`],generatingSteps:[`Visiting {url} to extract product details, specs, and category`,`Designing an agent to search AliExpress and rank suppliers by cost and reliability`,`Configuring landed cost calculations and margin analysis at $29.99 / $39.99 / $49.99`,`Setting up trademark screening and product card export`],featureSectionTitle:`From product link to sourcing decision`,featureCardTitles:[`Connects to your e-commerce stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`AliExpress, Shopify, Google Sheets, Notion, Amazon — Computer plugs into your tools so supplier research, costing, and product cards happen in one workflow.`,`Ranked supplier list with pricing. Landed cost breakdown at three price points. IP risk summary. Sample order instructions. One-page product card ready to share with your team.`],capabilitySectionTitle:`Your sourcing team, on autopilot`,capabilitySectionSubtitle:`Paste a product link, step away, come back to a complete sourcing report.`,capabilityCards:[{title:`Product Identification`,description:`Computer can analyze any product URL — extracting name, specs, materials, and category — to run a precise supplier search.`},{title:`Supplier Comparison`,description:`Computer can search AliExpress for every matching supplier and rank them by unit cost, shipping speed, MOQ, and seller rating.`},{title:`Margin Analysis`,description:`Computer can calculate landed costs and project profit margins at multiple retail price points — factoring in shipping, platform fees, and ad spend.`},{title:`Connect Your Tools`,description:`Computer can read and write to Shopify, Google Sheets, Notion, and more — build workflows across your entire sourcing and selling stack.`},{title:`Remember & Learn`,description:`Computer can remember your preferred suppliers, margin thresholds, and shipping requirements across sessions — so every search builds on what came before.`},{title:`Trend Monitoring`,description:`Computer can watch trending products and alert you when a new opportunity matches your niche — so you move before the market peaks.`}]});export{t as default};
